package com.erp.management.controller;
import com.erp.management.entity.Sale; import com.erp.management.repository.SaleRepository; import com.erp.management.service.TransactionService; import org.springframework.data.domain.Sort; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/sales") public class SalesController {private final TransactionService service;private final SaleRepository sales;public SalesController(TransactionService s,SaleRepository r){service=s;sales=r;} @PostMapping("/create") ResponseEntity<?> create(@RequestBody Sale sale){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("success",true,"invoice",service.createSale(sale)));}@GetMapping("/history") List<Sale> history(){return sales.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));}}
